      var responseProcessing = this.rootElement.responseProcessing;
      var processingType = responseProcessing && responseProcessing.processingType;
      var item, renderer;
      if (attrs) {
        response.attr(attrs);
      }
      item = this.getRootElement();
      item.addResponseDeclaration(response);
      var perInteractionRp = item.metaData.widget.options.perInteractionRp;
      response.buildIdentifier('RESPONSE', false);
      response.setTemplate(processingType === 'custom' ? 'CUSTOM' : template || 'MATCH_CORRECT');
      this.attr('responseIdentifier', response.id());
