define('taoQtiItem/qtiCreator/widgets/interactions/gapMatchInteraction/states/Correct',['lodash', 'i18n', 'taoQtiItem/qtiCreator/widgets/states/factory', 'taoQtiItem/qtiCreator/widgets/states/Correct', 'taoQtiItem/qtiCommonRenderer/renderers/interactions/GapMatchInteraction', 'taoQtiItem/qtiCommonRenderer/helpers/instructions/instructionManager', 'taoQtiItem/qtiCommonRenderer/helpers/PciResponse'], function (_, __, stateFactory, Correct, commonRenderer, instructionMgr, PciResponse) {
  var GapMatchInteractionStateCorrect = stateFactory.create(Correct, function () {
    var widget = this.widget;
    var interaction = widget.element;
    var response = interaction.getResponseDeclaration();
    var corrects = _.values(response.getCorrect());
    var instruction;
    var bodyLength = 0;
    var numberOfGaps = 0;
    if (interaction && interaction.bdy && interaction.bdy.bdy) {
      bodyLength = interaction.bdy.bdy.length;
    }
    if (interaction && interaction.bdy && interaction.bdy.elements) {
      numberOfGaps = Object.keys(interaction.bdy.elements).length;
    }
    commonRenderer.resetResponse(interaction);
    commonRenderer.destroy(interaction);
    if (bodyLength === 0) {
      instruction = __('This interaction has no text defined in question mode.');
    } else if (numberOfGaps === 0) {
      instruction = __('Please add one or more gaps to the text in question mode.');
    } else {
      instruction = __('Please fill the gap with the correct choices.');
    }
    instructionMgr.appendInstruction(interaction, instruction);
    commonRenderer.render.call(interaction.getRenderer(), interaction);
    commonRenderer.setResponse(interaction, PciResponse.serialize(_.invokeMap(corrects, String.prototype.split, ' '), interaction));
    widget.$container.on('responseChange.qti-widget', function (e, data) {
      var type = response.attr('cardinality') === 'single' ? 'base' : 'list';
      if (data.response && data.response[type]) {
        if (type === 'base') {
          response.setCorrect(data.response.base.directedPair.join(' '));
        } else {
          response.setCorrect(_.map(data.response.list.directedPair, function (pair) {
            return pair.join(' ');
          }));
        }
      } else {
        response.setCorrect([]);
      }
    });
  }, function () {
    var widget = this.widget;
    var interaction = this.widget.element;
    widget.$container.off('responseChange.qti-widget');
    commonRenderer.resetResponse(interaction);
    commonRenderer.destroy(interaction);
    instructionMgr.removeInstructions(interaction);
  });
  return GapMatchInteractionStateCorrect;
});
