define('taoQtiItem/qtiXmlRenderer/helper/scoringModelResponseProcessingGenerator',['lodash'], function (_) {
  'use strict';

  var DEFAULT_TEMP_SCORE_OUTCOME = 'TEMP_SCORE';
  var DEFAULT_SCORE_OUTCOME = 'SCORE';
  var normalizeConfig = function normalizeConfig(config) {
    var normalized = _.cloneDeep(config) || {};
    normalized.interactions = _.filter(normalized.interactions || [], _.isString);
    normalized.thresholds = _.chain(normalized.thresholds || []).map(entry => ({
      threshold: Number(entry.threshold),
      score: Number(entry.score)
    })).filter(entry => _.isFinite(entry.threshold) && _.isFinite(entry.score)).sortBy(entry => -entry.threshold).value();
    normalized.tempScoreOutcome = normalized.tempScoreOutcome || DEFAULT_TEMP_SCORE_OUTCOME;
    normalized.scoreOutcome = normalized.scoreOutcome || DEFAULT_SCORE_OUTCOME;
    return normalized;
  };
  var validateConfig = function validateConfig(config) {
    if (!config || !_.isObject(config)) {
      throw new TypeError('Scoring model response processing config must be an object');
    }
    if (!_.isArray(config.interactions) || !config.interactions.length) {
      throw new Error('Scoring model response processing requires at least one interaction identifier');
    }
    if (!_.isArray(config.thresholds) || !config.thresholds.length) {
      throw new Error('Scoring model response processing requires at least one threshold');
    }
  };
  var getMaxScore = function getMaxScore(config) {
    var normalized = normalizeConfig(config);
    if (!normalized.thresholds.length) {
      return 0;
    }
    return Math.max.apply(null, _.map(normalized.thresholds, 'score').concat([0]));
  };
  var buildMapToTempRule = function buildMapToTempRule(responseIdentifier, tempScoreOutcome) {
    return ['<responseCondition>', '    <responseIf>', '        <not>', '            <isNull>', "                <variable identifier=\"".concat(responseIdentifier, "\" />"), '            </isNull>', '        </not>', "        <setOutcomeValue identifier=\"".concat(tempScoreOutcome, "\">"), '            <sum>', "                <variable identifier=\"".concat(tempScoreOutcome, "\" />"), "                <mapResponse identifier=\"".concat(responseIdentifier, "\" />"), '            </sum>', '        </setOutcomeValue>', '    </responseIf>', '</responseCondition>'].join('\n');
  };
  var buildThresholdRules = function buildThresholdRules(thresholds, tempScoreOutcome, scoreOutcome) {
    var lines = ['<responseCondition>'];
    _.forEach(thresholds, (entry, index) => {
      var tag = index === 0 ? 'responseIf' : 'responseElseIf';
      lines.push("    <".concat(tag, ">"));
      lines.push('        <gte>');
      lines.push("            <variable identifier=\"".concat(tempScoreOutcome, "\" />"));
      lines.push("            <baseValue baseType=\"float\">".concat(entry.threshold, "</baseValue>"));
      lines.push('        </gte>');
      lines.push("        <setOutcomeValue identifier=\"".concat(scoreOutcome, "\">"));
      lines.push("            <baseValue baseType=\"float\">".concat(entry.score, "</baseValue>"));
      lines.push('        </setOutcomeValue>');
      lines.push("    </".concat(tag, ">"));
    });
    lines.push('    <responseElse>');
    lines.push("        <setOutcomeValue identifier=\"".concat(scoreOutcome, "\">"));
    lines.push('            <baseValue baseType="float">0</baseValue>');
    lines.push('        </setOutcomeValue>');
    lines.push('    </responseElse>');
    lines.push('</responseCondition>');
    return lines.join('\n');
  };
  var generateResponseProcessing = function generateResponseProcessing(config) {
    var normalized = normalizeConfig(config);
    validateConfig(normalized);
    var mapRules = _.map(normalized.interactions, responseIdentifier => buildMapToTempRule(responseIdentifier, normalized.tempScoreOutcome));
    var thresholdRules = buildThresholdRules(normalized.thresholds, normalized.tempScoreOutcome, normalized.scoreOutcome);
    return "<responseProcessing>\n".concat(mapRules.concat(thresholdRules).join('\n'), "\n</responseProcessing>");
  };
  return {
    DEFAULT_TEMP_SCORE_OUTCOME,
    DEFAULT_SCORE_OUTCOME,
    normalizeConfig,
    validateConfig,
    getMaxScore,
    buildMapToTempRule,
    buildThresholdRules,
    generateResponseProcessing
  };
});
